package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Runs in the create-owner pipeline after {@link BuildOwner} and before {@link SaveOwner}. Counts
 * the existing owners that already share this owner's firstName and lastName (compared
 * case-insensitively) at the moment before it is stored, and stamps that count onto the built owner
 * in place so later steps store and respond with it. As it runs before the owner is saved, the
 * count excludes the owner being created; the first owner of a name gets 0.
 */
public class AssignNamesakeCount {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = owner.getFirstName();
        String lastName = owner.getLastName();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (equalsIgnoreCase(firstName, existing.getFirstName())
                    && equalsIgnoreCase(lastName, existing.getLastName())) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }
}
===== AssignMembershipNumber =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Runs in the create-owner pipeline after {@link AssignCustomerCode} and
 * {@link DefaultOwnerRegistrationDate}, before {@link SaveOwner}. Assigns the owner's
 * {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'} where YY is the last two digits
 * of the fiscal year (starting 1 July) derived from the business-day-adjusted registrationDate, over
 * the region-and-hash customerCode (e.g. 'NSW-1A2B3C4D-M27'). The YY matches the owner's
 * {@link Owner#getFiscalYear() fiscalYear}. Mutates the built owner in place so later steps store and
 * respond with the assigned number.
 */
public class AssignMembershipNumber {

    public void service(@Val Owner owner) {
        String yy = String.format("%02d", Owner.fiscalYearOf(owner.getRegistrationDate()) % 100);
        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
    }
}
